#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/drawing/bitmap/bitmap.hpp"
#include "gui_forms/drawing/geometry/point_f/point_f.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <memory>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// RasterCanvas's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/raster_canvas.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The bitmap shown, shared with the application, or null for none. A new bitmap drops the published tiles and, when attached to a window, publishes the whole bitmap again.
template <typename Declaring>
struct RasterCanvasBitmapCapability {
    PropertyView<std::shared_ptr<gui_drawing::Bitmap>, RasterCanvasBitmapCapability<Declaring>> bitmap;

    static void assign(RasterCanvasBitmapCapability& capability, std::shared_ptr<gui_drawing::Bitmap> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.bitmap), std::move(incoming));
    }

    static std::shared_ptr<gui_drawing::Bitmap> read(const RasterCanvasBitmapCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::shared_ptr<gui_drawing::Bitmap> current = control.read_view(capability.bitmap);
        return current;
    }
};

// Client units per bitmap pixel, 1/64 to 256 (default 1). A value outside that range throws std::invalid_argument and changes nothing; set_view changes zoom and view_origin together.
template <typename Declaring>
struct RasterCanvasZoomCapability {
    PropertyView<double, RasterCanvasZoomCapability<Declaring>> zoom;

    static void assign(RasterCanvasZoomCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.zoom), std::move(incoming));
    }

    static double read(const RasterCanvasZoomCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        double current = control.read_view(capability.zoom);
        return current;
    }
};

// The bitmap point shown at the client's top-left corner. A non-finite or unbounded origin throws std::invalid_argument and changes nothing.
template <typename Declaring>
struct RasterCanvasViewOriginCapability {
    PropertyView<gui_drawing::PointF, RasterCanvasViewOriginCapability<Declaring>> view_origin;

    static void assign(RasterCanvasViewOriginCapability& capability, gui_drawing::PointF incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.view_origin), std::move(incoming));
    }

    static gui_drawing::PointF read(const RasterCanvasViewOriginCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        gui_drawing::PointF current = control.read_view(capability.view_origin);
        return current;
    }
};

// How magnified or reduced pixels are sampled (default nearest). A value outside the enumeration throws std::invalid_argument.
template <typename Declaring>
struct RasterCanvasSamplingCapability {
    PropertyCell<ImageSampling, RasterCanvasSamplingCapability<Declaring>> sampling{ImageSampling::nearest};

    static void assign(RasterCanvasSamplingCapability& capability, ImageSampling incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.sampling), incoming);
        if (!capability.sampling.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.sampling));
    }
};

// Whether transparent pixels show a checkerboard (default true).
template <typename Declaring>
struct RasterCanvasTransparencyGridCapability {
    PropertyCell<bool, RasterCanvasTransparencyGridCapability<Declaring>> transparency_grid{true};

    static void assign(RasterCanvasTransparencyGridCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.transparency_grid), incoming);
        if (!capability.transparency_grid.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.transparency_grid));
    }
};

// The fill around the bitmap.
template <typename Declaring>
struct RasterCanvasCanvasBackgroundCapability {
    PropertyCell<Color, RasterCanvasCanvasBackgroundCapability<Declaring>> canvas_background{Color::rgba(112, 118, 126)};

    static void assign(RasterCanvasCanvasBackgroundCapability& capability, Color incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.canvas_background), incoming);
        if (!capability.canvas_background.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.canvas_background));
    }
};

// The checkerboard cell size in client units, 2 to 128; zero (the default) selects an adaptive bounded size. Any other value throws std::invalid_argument.
template <typename Declaring>
struct RasterCanvasTransparencyCellSizeCapability {
    PropertyCell<double, RasterCanvasTransparencyCellSizeCapability<Declaring>> transparency_cell_size{0.0};

    static void assign(RasterCanvasTransparencyCellSizeCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.transparency_cell_size), incoming);
        if (!capability.transparency_cell_size.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.transparency_cell_size));
    }
};

// Every RasterCanvas capability, in the order the declaring class takes them.
template <typename Declaring>
struct RasterCanvasCapabilities : public RasterCanvasBitmapCapability<Declaring>,
                                  public RasterCanvasZoomCapability<Declaring>,
                                  public RasterCanvasViewOriginCapability<Declaring>,
                                  public RasterCanvasSamplingCapability<Declaring>,
                                  public RasterCanvasTransparencyGridCapability<Declaring>,
                                  public RasterCanvasCanvasBackgroundCapability<Declaring>,
                                  public RasterCanvasTransparencyCellSizeCapability<Declaring> {};

} // namespace gui_forms
